// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address sender, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);

        vm.assume(amount > 0);

        vm.deal(sender, amount);

        bool ok;
        vm.prank(sender);
        (bool success,) = address(c).call{value: amount}("");
        ok = success;

        if (ok) {
            assertTrue(c.depositsCount() == 1 && address(c).balance == amount);
        } else {
            assertTrue(ok);
        }
    }
}
